<template><view class="page reading-page"><view class="back" @tap="back">‹</view><view v-if="article.title" class="article card"><text class="category">{{article.category}}</text><text class="title">{{article.title}}</text><text class="meta">每日阅读 · 已阅读 {{seconds}} / {{requiredSeconds}} 秒</text><text class="content">{{article.content}}</text><view class="reading-track"><view :style="{width:Math.min(seconds/requiredSeconds*100,100)+'%'}"/></view><text v-if="completed" class="done">今日阅读已完成，获得 {{points}} 积分</text><text v-else class="hint">请保持页面打开，阅读满 1 分钟即可获得积分</text></view><view v-else class="empty card">正在加载今日文章…</view></view></template>
<script>
import { callCloud } from '../../common/cloud.js'
import { toast } from '../../common/mock.js'
export default { data(){return{article:{},seconds:0,requiredSeconds:60,completed:false,points:0,timer:null}}, async onLoad(){try{const result=await callCloud('carbon-article-today');this.article=result.data||{};this.requiredSeconds=result.requiredSeconds||60;this.timer=setInterval(()=>{if(this.completed)return;this.seconds++;if(this.seconds>=this.requiredSeconds)this.complete()},1000)}catch(error){toast(error.message||'文章加载失败')}},onUnload(){clearInterval(this.timer)},methods:{async complete(){clearInterval(this.timer);try{const session=uni.getStorageSync('user_session')||{};const result=await callCloud('carbon-article-complete',{userId:session.id,articleId:this.article._id,durationSeconds:this.seconds});this.completed=true;this.points=result.points||0;if(!result.duplicate)uni.setStorageSync('user_points',Number(uni.getStorageSync('user_points')||0)+this.points)}catch(error){toast(error.message||'阅读完成失败')}},back(){uni.navigateBack()}}}
</script>
<style lang="scss">@import '../../common/portal.scss';.reading-page{padding-top:18rpx}.back{width:68rpx;height:68rpx;font-size:58rpx}.article{margin-top:28rpx;padding:32rpx}.category{color:#398052;font-size:24rpx}.title{display:block;margin-top:18rpx;color:#17231b;font-size:40rpx;font-weight:700;line-height:1.35}.meta{display:block;margin-top:18rpx;color:#88948d;font-size:22rpx}.content{display:block;margin-top:32rpx;color:#53615f;font-size:27rpx;line-height:2}.reading-track{height:14rpx;margin-top:34rpx;border-radius:20rpx;background:#e5ebe7;overflow:hidden}.reading-track view{height:100%;border-radius:20rpx;background:#27ae60}.hint,.done{display:block;margin-top:20rpx;color:#398052;font-size:23rpx}.done{font-weight:700}.empty{margin-top:30rpx;padding:50rpx;text-align:center}</style>
